# c216: 체력바 — 가로 고정 (나 = 지금 길이 · 동료·적·사물 = 동료 바의 2배) · 늘어난 체력은 색 겹으로 (보스 제외)
C216_R = [
 ("  function chHpFill(b) {                       // c65: 한 겹을 넘는 체력은 초록 위를 파랑으로, 두 겹을 넘으면 주황으로 덮는다\n    const C = CH_HP_CAP, M = b.maxHp || 1, h = Math.max(0, b.hpDisp);\n    if (M <= C + 1e-6 || b.oneBar) { b.hpFill.scale.x = Math.max(0.001, h / M); if (b.hpFill2) b.hpFill2.visible = b.hpFill3.visible = b.hpFill4.visible = false; return; }\n    if (!b.hpFill2) for (const [k, mat, n] of [['hpFill2', chHpMat2, 1], ['hpFill3', chHpMat3, 2], ['hpFill4', chHpMat4, 3]]) { const m = new THREE.Mesh(gaugeFillGeo, mat); m.position.copy(b.hpFill.position); m.position.z += 0.001 * n; m.renderOrder = b.hpFill.renderOrder + n; b.hpBar.add(m); b[k] = m; }\n    const f2 = Math.min(1, Math.max(0, h - C) / C), f3 = Math.min(1, Math.max(0, h - 2 * C) / C), f4 = Math.min(1, Math.max(0, h - 3 * C) / C);\n    b.hpFill.scale.x = Math.max(0.001, Math.min(h, C) / C);\n    b.hpFill2.visible = f2 > 0; b.hpFill2.scale.x = Math.max(0.001, f2);\n    b.hpFill3.visible = f3 > 0; b.hpFill3.scale.x = Math.max(0.001, f3);\n    b.hpFill4.visible = f4 > 0; b.hpFill4.scale.x = Math.max(0.001, f4);\n", "  function chHpFill(b) {                       // c216: 가로는 고정 · 한 겹(나 = 내 기본 최대 체력, 그 밖 = 동료 기본 최대 체력)을 넘는 만큼은 색을 겹친다 (초록 → 파랑 → 보라 → 빨강 → 다시 초록)\n    const h = Math.max(0, b.hpDisp);\n    if (b.oneBar) { b.hpFill.scale.x = Math.max(0.001, h / (b.maxHp || 1)); return; }   // 보스는 그대로\n    if (!b.hpMat0) b.hpMat0 = b.hpFill.material;\n    if (!b.hpFill2) for (const [k, mat, n] of [['hpFill2', chHpMat2, 1], ['hpFill3', chHpMat3, 2], ['hpFill4', chHpMat4, 3]]) { const m = new THREE.Mesh(gaugeFillGeo, mat); m.position.copy(b.hpFill.position); m.position.z += 0.001 * n; m.renderOrder = b.hpFill.renderOrder + n; m.visible = false; b.hpBar.add(m); b[k] = m; }\n    const U = b === me ? MY_HP : ALLY_HP * 0.9, M = [b.hpMat0, chHpMat2, chHpMat3, chHpMat4];\n    const k = h > 1e-6 ? Math.floor((h - 1e-6) / U) : 0, f = (h - k * U) / U;\n    b.hpFill3.visible = b.hpFill4.visible = false;\n    if (k === 0) { b.hpFill.material = M[0]; b.hpFill.scale.x = Math.max(0.001, f); b.hpFill2.visible = false; return; }\n    b.hpFill.material = M[(k - 1) % 4]; b.hpFill.scale.x = 1;\n    b.hpFill2.material = M[k % 4]; b.hpFill2.visible = true; b.hpFill2.scale.x = Math.max(0.001, f);\n"),
 ("  const barW = (b, mine) => Math.max(0.001, (mine ?", "  const barW = (b, mine) => CHAPTER && !b.oneBar ? (mine ? 1.2 * 1.2 * 1.2 * 2 / 3 * 2 / 3 : 2 * 0.5 / POLICE_HP * ALLY_HP * 0.9) : Math.max(0.001, (mine ?   /* c216: 가로 고정 */"),
 ("if (CHAPTER && b !== me) chHpFill(b); else b.hpFill.scale.x", "if (CHAPTER) chHpFill(b); else b.hpFill.scale.x"),
]
